parameters.html:
=<!DOCTYPE html>
<html lang="ar" dir="rtl" xmlns="http://www.w3.org/1999/xhtml">

<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta http-equiv="X-UA-Compatible" content="IE=edge">
    <meta name="x-apple-disable-message-reformatting">

    <title>تذكير بموعد تجديد علاجك</title>

    <style>
        body {
            margin: 0 !important;
            padding: 0 !important;
            width: 100% !important;
            background-color: #f4f7f8;
            font-family: Arial, Tahoma, sans-serif;
            color: #172033;
        }

        table {
            border-spacing: 0 !important;
            border-collapse: collapse !important;
        }

        img {
            border: 0;
            outline: none;
            text-decoration: none;
        }

        a {
            text-decoration: none;
        }

        .container {
            width: 600px;
            max-width: 600px;
        }

        @media screen and (max-width: 620px) {

            .container {
                width: 100% !important;
                max-width: 100% !important;
            }

            .side-padding {
                padding-left: 18px !important;
                padding-right: 18px !important;
            }

            .hero-title {
                font-size: 26px !important;
            }

            .medicine-name {
                font-size: 19px !important;
            }

            .coupon-code {
                font-size: 28px !important;
            }
        }
    </style>
</head>

<body>

<center style="width:100%; background-color:#f4f7f8;">

    <!-- PREHEADER -->
    <div style="
        display:none;
        max-height:0;
        overflow:hidden;
        opacity:0;
        color:transparent;
        font-size:1px;
        line-height:1px;
    ">
        تذكير بموعد تجديد علاجك من صيدلية AI-COS.
    </div>

    <table role="presentation" width="100%">
        <tr>
            <td align="center" style="padding:18px 10px;">

                <!-- MAIN CONTAINER -->
                <table
                    role="presentation"
                    class="container"
                    width="600"
                    style="
                        width:600px;
                        max-width:600px;
                        background:#ffffff;
                        border-radius:18px;
                        overflow:hidden;
                        border:1px solid #e4eaee;
                    "
                >

                    <!-- BRAND -->
                    <tr>
                        <td
                            align="center"
                            class="side-padding"
                            style="padding:20px 30px 12px 30px;"
                        >

                            <div style="
                                font-size:21px;
                                font-weight:800;
                                color:#087f78;
                            ">
                                🏥 صيدلية AI-COS
                            </div>

                        </td>
                    </tr>


                    <!-- DIVIDER -->
                    <tr>
                        <td style="padding:0 30px;">
                            <div style="
                                height:1px;
                                background:#edf1f3;
                            "></div>
                        </td>
                    </tr>


                    <!-- HERO -->
                    <tr>
                        <td
                            align="center"
                            class="side-padding"
                            style="padding:20px 35px 16px 35px;"
                        >

                            <!-- BADGE -->
                            <div style="
                                display:inline-block;
                                padding:5px 13px;
                                border-radius:30px;
                                border:1px solid #b7eadf;
                                background:#effbf8;
                                color:#087f78;
                                font-size:12px;
                                font-weight:700;
                            ">
                                💚 تذكير صحي
                            </div>

                            <!-- TITLE -->
                            <h1
                                class="hero-title"
                                style="
                                    margin:13px 0 8px 0;
                                    font-size:28px;
                                    line-height:1.3;
                                    color:#15202b;
                                    font-weight:800;
                                "
                            >
                                حان موعد تجديد علاجك
                            </h1>

                            <!-- GREETING -->
                            <p style="
                                margin:0;
                                font-size:15px;
                                line-height:1.65;
                                color:#64748b;
                            ">
                                مرحباً أستاذ
                                <strong style="color:#334155;">
                                    {{ $('1. Pull Pending Reminders').item.json.customer_name }}
                                </strong>
                                👋
                                <br>
                                نتمنى لك دوام الصحة والعافية 💙
                            </p>

                        </td>
                    </tr>


                    <!-- PERSONAL MESSAGE -->
                    <tr>
                        <td
                            class="side-padding"
                            style="padding:0 35px 18px 35px;"
                        >

                            <div style="
                                background:#f8fafb;
                                border-right:4px solid #0f766e;
                                border-radius:10px;
                                padding:14px 18px;
                                color:#475569;
                                font-size:14px;
                                line-height:1.7;
                            ">

                                {{ $('2.5 Marketing Agent').item.json.message_text }}

                            </div>

                        </td>
                    </tr>


                    <!-- MEDICINE CARD -->
                    <tr>
                        <td
                            class="side-padding"
                            style="padding:0 35px 18px 35px;"
                        >

                            <table
                                role="presentation"
                                width="100%"
                                style="
                                    background:#f8fafc;
                                    border:1px solid #e2e8f0;
                                    border-radius:13px;
                                "
                            >

                                <tr>

                                    <td
                                        align="center"
                                        style="padding:17px 15px;"
                                    >

                                        <div style="
                                            font-size:13px;
                                            font-weight:700;
                                            color:#64748b;
                                            margin-bottom:6px;
                                        ">
                                            💊 علاجك المجدول
                                        </div>

                                        <div
                                            class="medicine-name"
                                            style="
                                                font-size:21px;
                                                font-weight:800;
                                                color:#087f78;
                                                line-height:1.35;
                                            "
                                        >
                                            {{ $('1. Pull Pending Reminders').item.json.drug_name }}
                                        </div>

                                        <div style="
                                            margin-top:5px;
                                            font-size:12px;
                                            color:#94a3b8;
                                        ">
                                            ⏰ حان موعد التجديد
                                        </div>

                                    </td>

                                </tr>

                            </table>

                        </td>
                    </tr>


                    <!-- COUPON -->
                    {{ $('2.5 Marketing Agent').item.json.coupon_code ? `

                    <tr>

                        <td
                            class="side-padding"
                            style="padding:0 35px 20px 35px;"
                        >

                            <table
                                role="presentation"
                                width="100%"
                                style="
                                    background:#fff9eb;
                                    border:1px solid #f2c66d;
                                    border-radius:14px;
                                "
                            >

                                <tr>

                                    <td
                                        align="center"
                                        style="padding:18px 15px;"
                                    >

                                        <div style="
                                            font-size:14px;
                                            font-weight:800;
                                            color:#92400e;
                                            margin-bottom:5px;
                                        ">
                                            🎁 هدية خاصة تقديراً لالتزامك
                                        </div>

                                        <div style="
                                            font-size:13px;
                                            color:#78350f;
                                            margin-bottom:11px;
                                        ">
                                            خصم 15% على إعادة طلب علاجك
                                        </div>


                                        <table role="presentation">
                                            <tr>

                                                <td
                                                    class="coupon-code"
                                                    style="
                                                        background:#ffffff;
                                                        border:2px dashed #d97706;
                                                        border-radius:8px;
                                                        padding:9px 24px;
                                                        font-family:Courier New, monospace;
                                                        font-size:30px;
                                                        font-weight:900;
                                                        letter-spacing:3px;
                                                        color:#172033;
                                                    "
                                                >
                                                    ${ $('2.5 Marketing Agent').item.json.coupon_code }
                                                </td>

                                            </tr>
                                        </table>


                                        <div style="
                                            margin-top:9px;
                                            font-size:12px;
                                            color:#78350f;
                                        ">
                                            📋 استخدم الكود أثناء إتمام الطلب.
                                        </div>

                                    </td>

                                </tr>

                            </table>

                        </td>

                    </tr>

                    ` : "" }}


                    <!-- CTA -->
                    <tr>

                        <td
                            align="center"
                            class="side-padding"
                            style="padding:0 35px 6px 35px;"
                        >

                            <table role="presentation">
                                <tr>

                                    <td
                                        align="center"
                                        style="
                                            background:#16a34a;
                                            border-radius:10px;
                                        "
                                    >

                                        <a
                                            href="https://dawaagate.com/reorder"
                                            target="_blank"
                                            style="
                                                display:inline-block;
                                                padding:14px 42px;
                                                color:#ffffff;
                                                font-family:Arial,Tahoma,sans-serif;
                                                font-size:16px;
                                                font-weight:800;
                                            "
                                        >
                                            استكمال إعادة الطلب
                                        </a>

                                    </td>

                                </tr>
                            </table>

                        </td>

                    </tr>


                    <!-- MICRO COPY -->
                    <tr>

                        <td
                            align="center"
                            style="padding:5px 25px 18px 25px;"
                        >

                            <div style="
                                color:#94a3b8;
                                font-size:11px;
                            ">
                                ⏱️ لن تستغرق عملية التجديد أكثر من دقيقة.
                            </div>

                        </td>

                    </tr>


                    <!-- TRUST -->
                    <tr>

                        <td
                            style="
                                padding:0 25px 20px 25px;
                                border-top:1px solid #edf1f3;
                            "
                        >

                            <table
                                role="presentation"
                                width="100%"
                                style="margin-top:16px;"
                                dir="rtl"
                            >

                                <tr>

                                    <td
                                        align="center"
                                        width="33%"
                                    >

                                        <div style="font-size:19px;">
                                            🚚
                                        </div>

                                        <div style="
                                            margin-top:3px;
                                            font-size:12px;
                                            font-weight:700;
                                            color:#475569;
                                        ">
                                            توصيل سريع
                                        </div>

                                    </td>


                                    <td
                                        align="center"
                                        width="33%"
                                    >

                                        <div style="font-size:19px;">
                                            🔒
                                        </div>

                                        <div style="
                                            margin-top:3px;
                                            font-size:12px;
                                            font-weight:700;
                                            color:#475569;
                                        ">
                                            دفع آمن
                                        </div>

                                    </td>


                                    <td
                                        align="center"
                                        width="33%"
                                    >

                                        <div style="font-size:19px;">
                                            👨‍⚕️
                                        </div>

                                        <div style="
                                            margin-top:3px;
                                            font-size:12px;
                                            font-weight:700;
                                            color:#475569;
                                        ">
                                            دعم صيدلي
                                        </div>

                                    </td>

                                </tr>

                            </table>

                        </td>

                    </tr>


                    <!-- FOOTER -->
                    <tr>

                        <td
                            align="center"
                            style="
                                background:#f8fafc;
                                border-top:1px solid #edf1f3;
                                padding:16px 25px;
                            "
                        >

                            <div style="
                                font-size:12px;
                                line-height:1.6;
                                color:#64748b;
                            ">
                                شكراً لثقتكم بصيدلية AI-COS 💙
                                <br>
                                نحن هنا دائماً لخدمتكم.
                            </div>

                        </td>

                    </tr>

                </table>

            </td>
        </tr>
    </table>

</center>

</body>
</html>

